window.SCREENS = [{"id": "2.0", "type": "cover", "menu": "Pre-Season Conditioning", "dark": true, "photo": "ai_focus_eyes", "kicker": "LESSON 2", "heading": "Pre-Season Conditioning", "meta": "About 40 minutes. Then one core rep this week.", "cta": "Start Lesson", "lesson": "L2", "vo": ["n_2_0"], "sec": ""}, {"id": "2.1", "type": "moment", "menu": "The Moment", "dark": true, "photo": "ai_plant_monday_news", "scene": "It's Monday at 8:10 a.m. Over the weekend, leadership decided to bring in a new AI tool for your team's work. The plan your team agreed on two weeks ago is on hold, and the part you cared about most is going to the tool. Your first message to the team is due before the 9:00 a.m. team meeting.", "lesson": "L2", "vo": ["n_2_1"], "sec": "Notice"}, {"id": "2.2", "type": "checkin", "menu": "Check-In", "anchor": "Name the value this change touches.", "lesson": "L2", "vo": ["ci_a", "ci_b", "ci_c"], "sec": "Notice"}, {"id": "2.3", "type": "recall", "menu": "Last Time", "q": "Which sentence describes conditioning?", "opts": ["What you know well when you have time to think", "What you can access when there's no time to think"], "correct": 1, "ok": "Right. What you can access under pressure starts with what you know about yourself, and that's where this lesson starts.", "no": "It's the second one: What you can access when there's no time to think.", "lesson": "L2", "vo": ["n_2_3"], "sec": "Notice"}, {"id": "2.4", "type": "objectives", "menu": "What You Will Practice", "photo": "ai_coach_colleague", "practise": "When the plan changes, choose your next move on purpose.", "objs": [["Name your core values.", "Three to five you would hold at a cost", 1, "core"], ["Tell a strength from a skill.", "A strength also tends to give you energy.", 2], ["Map your energy.", "What fuels you and what drains you", 3], ["Read your game tape.", "One high point, one setback", 4]], "lesson": "L2", "vo": ["n_2_4"], "sec": "Notice"}, {"id": "2.5", "type": "fullvideo", "menu": "Video 2.1: Your Inner Blueprint", "video": "p2_1", "label": "Lesson 2.1", "sub": "Locker Room Briefing: Your Inner Blueprint", "lesson": "L2", "mlabel": "Your Inner Blueprint", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.6", "type": "fullvideo", "menu": "Video 2.2: Your Core Values", "video": "p2_2", "label": "Lesson 2.2", "sub": "Identifying your core values", "lesson": "L2", "mlabel": "Your Core Values", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.7", "type": "tabs", "menu": "Your Inner Blueprint", "gate": true, "kind": "blueprint", "eyebrow": "YOUR INNER BLUEPRINT", "heading": "Four parts to collect this week", "items": [{"k": "values", "name": "Values", "sub": "What you'd hold even at a cost", "big": "3 to 5", "line": "From a long list, narrowed down", "icon": "V"}, {"k": "strengths", "name": "Strengths", "sub": "What you do well that also gives you energy", "big": "Energy +", "line": "Good at it, and it tends to fuel you", "icon": "S"}, {"k": "energy", "name": "Energy", "sub": "What fuels you and what drains you?", "big": "3 + 3", "line": "Drains and fuels, from a real week", "icon": "E"}, {"k": "tape", "name": "Game tape", "sub": "What your best and worst moments show?", "big": "1 + 1", "line": "One high point, one setback", "icon": "G"}], "lesson": "L2", "vo": ["n_2_7"], "itemvo": {"values": "n_2_7_values", "strengths": "n_2_7_strengths", "energy": "n_2_7_energy", "tape": "n_2_7_tape"}, "sec": "Learn and Decide"}, {"id": "2.8", "type": "fullvideo", "menu": "Video 2.3: Your Strengths", "video": "p2_3", "label": "Lesson 2.3", "sub": "Understanding your strengths", "lesson": "L2", "mlabel": "Your Strengths", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.9", "type": "sort", "menu": "Strength or Skill?", "bins": ["Strength", "Skill"], "photo": "man_writing", "heading": "Strength or skill?", "sub": "Sort each one. The clue: Don't just ask, “Am I good at this?” Ask, “Does doing this tend to energize me?”", "items": [["You lose track of time doing it, and you often finish energized.", 0, "It gives you energy back: a strength."], ["You're good at it, but you tend to put it off whenever you can.", 1, "You're good at it, and you'd rather put it off: more likely a skill."], ["People come to you for it, and you genuinely enjoy doing it.", 0, "People seek it out and you enjoy it: a strength."], ["You do it well, but it consistently takes more energy than it gives.", 1, "You do it well, and it costs more than it gives: a skill you've built."]], "lesson": "L2", "vo": ["n_2_9"], "sec": "Learn and Decide"}, {"id": "2.10", "type": "fullvideo", "menu": "Video 2.4: Mapping Your Energy", "video": "p2_4", "label": "Lesson 2.4", "sub": "Mapping Your Energy", "lesson": "L2", "mlabel": "Mapping Your Energy", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.11", "type": "fullvideo", "menu": "Video 2.5: Your Game Tape", "video": "p2_5", "label": "Lesson 2.5", "sub": "Reviewing Your Game Tape", "lesson": "L2", "mlabel": "Your Game Tape", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.12", "type": "example", "menu": "Melissa's Game Tape", "photo": "ai_start_line_detail", "eyebrow": "GAME TAPE", "heading": "How Melissa read her own setback", "blocks": [["The situation", "Two NFL teams turned down her idea for player development."], ["What she did", "Treated the no as feedback and kept refining the idea."], ["What happened?", "Three years later, the NFL said yes, and Player Brand University launched across the entire league."], ["The practice", "This week, when you hear a no, ask what it can teach you before you decide your next move."]], "lesson": "L2", "vo": ["n_2_12"], "sec": "Learn and Decide"}, {"id": "2.13", "type": "call", "menu": "Make the Call", "photo": "ai_plant_pause_decide", "prompt": "It's Monday at 8:10 a.m. Your message to the team is due before the 9:00 a.m. meeting. You named a value in this lesson. What do you do first?", "opts": [{"t": "Reply immediately, defending the original plan and explaining why changing course is a mistake.", "fb": "You spend the hour defending a plan that's already changed.", "vo": "n_2_13_o0"}, {"t": "Pause. Go back to the value you named. Ask yourself: “What would leading from this value look like right now?” Then decide how you want to respond.", "fb": "That's the rep. Your value doesn't tell you what decision to make. It gives you a filter for how you want to lead through it. The plan changed. The pressure went up. Your value helps you choose who you want to be in the moment.", "best": true, "vo": "n_2_13_o1"}], "lesson": "L2", "vo": ["n_2_13"], "sec": "Learn and Decide"}, {"id": "2.14", "type": "fullvideo", "menu": "Video 2.6: Next Play", "video": "p2_6", "label": "Lesson 2.6", "sub": "Next Play", "endnote": "One short drill first, then your Lesson 2 Playbook pages.", "lesson": "L2", "mlabel": "Next Play", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.15", "type": "drill", "menu": "The Drill: The Plan Just Changed", "drill": "L2", "lesson": "L2", "vo": ["n_2_15"], "video": "drill_l2", "mkind": "video", "sec": "Learn and Decide"}, {"id": "2.16", "type": "playbook", "menu": "Condition the Reps", "cover": "assets/playbook_cover.jpg", "pdf": "resources/Athleader_Playbook_Lesson2.pdf", "total": "60", "core": 0, "drills": [["2.1", "Discover your core values", "Alignment", 15, 0], ["2.2", "Identify your strengths", "Wellbeing", 15, 1], ["2.3", "Your energy audit", "Wellbeing", 15, 1], ["2.4", "Review your game tape", "Resilience", 15, 2]], "lesson": "L2", "vo": ["n_2_16"], "sec": "Practice"}, {"id": "2.17", "type": "huddle", "menu": "Athleader Pro Huddle", "pro": "mannino", "video": "pro_mannino", "lesson": "L2", "vo": ["n_2_17"], "mkind": "video", "sec": "Practice"}, {"id": "2.18", "type": "prodrill", "menu": "Michael's 3-Minute Drill", "pro": "mannino", "lesson": "L2", "vo": ["n_2_18"], "sec": "Practice"}, {"id": "2.19", "type": "pulse", "menu": "Pulse Check", "n": 2, "lesson": "L2", "vo": ["r2_pulse"], "next_line": "The Pulse Check opens on the next screen.", "sec": "Measure"}, {"id": "2.19a", "type": "formembed", "menu": "Pulse Check: The Form", "form": "pulse", "eyebrow": "PULSE CHECK · LESSON 2", "heading": "Your Pulse Check", "note": "Your code is on the last page. Copy the code or write it down, then select Next.", "fallback": "Form not loading? Open it in a new tab.", "lesson": "L2", "vo": ["r2_form_pulse"], "n": 2, "mlabel": "Take the Pulse Check", "sec": "Measure"}, {"id": "2.19b", "type": "formcode", "menu": "Pulse Check: Your Code", "form": "pulse", "gate": "pulse2", "eyebrow": "PULSE CHECK · LESSON 2", "heading": "Enter your code.", "prompt": "The code from the last page of the Pulse Check", "button": "Submit", "ok": "Accepted. Your Lesson 2 Pulse Check is in.", "back": "Back to the form", "lesson": "L2", "vo": ["r2_code_pulse"], "n": 2, "mlabel": "Enter Your Code", "sec": "Measure"}, {"id": "2.20", "type": "kc", "menu": "Knowledge Check", "key": "kc2", "qs": [{"q": "You're excellent at building financial models, and people often ask you for them. You do it well, but it rarely gives you energy. In this system, that's a…", "opts": ["Strength", "Skill", "Value", "Drain"], "correct": 1, "fb": "It's a skill.", "why": "It's a skill: something you've learned to do well. Skills matter, and the moment often calls for them. A strength is something you do well that also tends to give you energy.", "vo": "n_2_20_q0", "wvo": "n_2_20_w0"}, {"q": "How many core values should you aim to name?", "opts": ["Just one", "Seven to ten", "Three to five", "As many as apply"], "correct": 2, "fb": "Three to five.", "why": "Three to five. With a long list of values, you have no way to choose between them when it matters.", "vo": "n_2_20_q1", "wvo": "n_2_20_w1"}, {"q": "When you review your game tape, what are you looking for?", "opts": ["Patterns in what you did and what your actions show", "Who or what caused the setback, so it won't recur", "Proof that you made the right call at the time", "The moments you would rather leave behind"], "correct": 0, "fb": "Patterns in what you did.", "why": "Patterns. Read it the way a coach reads film: what you did, and what it shows about you.", "vo": "n_2_20_q2", "wvo": "n_2_20_w2"}], "lesson": "L2", "sec": "Measure"}, {"id": "2.21", "type": "summary", "menu": "What You Conditioned Today", "lesson_no": 2, "points": [["Values are your filter", 1], ["A strength also gives you energy", 2], ["Setbacks are data", 3]], "book": "Chapter 8, p.125", "book_note": "Resilience: Lose No Lessons", "lesson": "L2", "vo": ["n_2_21"], "sec": "Wrap-Up"}, {"id": "2.22", "type": "close", "menu": "Lesson 2 Complete", "dark": true, "photo": "ai_pc_coach_walk", "n": 2, "heading": "Lesson 2 complete", "thisweek": "Your core rep: your values. Then ask one person how it landed.", "next": "Lesson 3, Game Plan: Define Your M.V.P.", "nextline": "Draft your purpose, vision, and mission.", "lesson": "L2", "vo": ["n_2_22"], "sec": "Wrap-Up", "last": true}];
window.PROS = {"mannino": {"name": "Dr. Michael Mannino", "nick": "The Flow Alchemist", "title": "PhD, Co-Founder, Syneurgy", "img": "assets/pro_mannino.jpg", "pillar": "Resilience", "quote": "Bridging neuroscience and peak performance to align identity with team flow.", "drill": "The Flow Sync", "drillSub": "3 minutes to build team resilience", "team": true, "steps": [["Identify the Challenge", 60, "As a team, name the biggest stressor right now."], ["Sync the Focus", 90, "Each person names the top priority and one blocker to that outcome. Capture the common thread."], ["Flow Trigger Action", 30, "Collectively agree on one small action today to move forward together: timebox deep work, solve for the blocker, or celebrate a win."]]}};
window.DRILLS = {"L2": {"video": "drill_l2", "title": "The Plan Just Changed", "tag": "CHANGE", "nar": ["Time for the drill. The Moment gave you time to think. This drill gives you a few seconds under a little pressure to see how you respond.", "Press Play. The video stops a few times so you can answer, and it resumes when you're done. Your Playbook pages come right after."], "opts": ["Push back and defend the original plan", "Quietly absorb it and adjust on your own", "Go to the people affected and rebuild together", "Pause and ask questions before reacting"], "optsAt": [65.1, 69.25, 74.85, 79.85], "beats": [{"t": 14.2, "u": 27.4, "kind": "shift", "text": "The plan just changed. What you built for the last few months is no longer the priority."}, {"t": 27.4, "u": 37.5, "kind": "notice", "text": "What do you notice? In your body, your thoughts, your urge to act."}, {"t": 48.5, "u": 64.3, "kind": "reframe", "text": "Whatever you notice is your system's opening move under change. The skill is choosing your next move on purpose."}, {"t": 65.1, "u": 84.1, "kind": "options", "text": "Your options"}, {"t": 89.2, "u": 95.1, "kind": "again", "text": "Same pressure, one more time. Try the option you didn't pick."}, {"t": 104.05, "u": 113.7, "kind": "condition", "text": "You just practiced the option that isn't automatic yet. That's what conditioning feels like before the moment demands it."}], "holds": [{"t": 37.5, "resume": 48.3, "key": "notice", "kind": "text", "label": "NOTICE", "q": "Before you respond, what do you notice? In your body, your thoughts, your urge to act."}, {"t": 84.1, "resume": 89.1, "key": "choose", "kind": "choice", "label": "CHOOSE", "q": "What do you do first?"}, {"t": 95.1, "resume": 103.9, "key": "again", "kind": "choice", "label": "GO AGAIN", "q": "Same pressure. Try the option you didn't pick.", "exclude": "choose"}]}};
